export function photoFor(p){return photos[p.template?'template:'+p.template:p.kind+':'+String(p.name||'').trim()]||''}
export function merge(existing){return existing.map(p=>p.photo?p:photoFor(p)?{...p,photo:photoFor(p)}:p)}
